import{_ as i}from"./chunks/embed-playground.DUFBb3fy.js";import{_ as t,o as e,c as l,ai as s}from"./chunks/framework.C33Uq6m-.js";const u=JSON.parse('{"title":"嵌入","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/embeddings.md","filePath":"zh/guide/embeddings.md"}'),o={name:"zh/guide/embeddings.md"};function r(n,a,d,h,c,g){return e(),l("div",null,[...a[0]||(a[0]=[s('<h1 id="嵌入" tabindex="-1">嵌入 <a class="header-anchor" href="#嵌入" aria-label="Permalink to &quot;嵌入&quot;">​</a></h1><p>嵌入页让你生成文本嵌入，并直观地比较两段文字在语义上有多相似。</p><p><strong>侧边栏位置：</strong> 嵌入 <strong>路由：</strong> <code>/embeddings</code></p><p><img src="'+i+'" alt="嵌入实验台"></p><h2 id="什么是嵌入" tabindex="-1">什么是嵌入？ <a class="header-anchor" href="#什么是嵌入" aria-label="Permalink to &quot;什么是嵌入？&quot;">​</a></h2><p>嵌入是一串数字（一个向量），用来表示一段文字的含义。含义相近的文字，会产生方向相近的向量。LLMxRay 利用这个概念，让你可以动手探索语义相似度。</p><h2 id="为文本生成嵌入" tabindex="-1">为文本生成嵌入 <a class="header-anchor" href="#为文本生成嵌入" aria-label="Permalink to &quot;为文本生成嵌入&quot;">​</a></h2><ol><li>从下拉框中选择一个<strong>嵌入模型</strong>。只有具备嵌入能力的模型才会出现（例如 <code>nomic-embed-text</code>、<code>all-minilm</code>）。</li><li>在输入区输入文字。</li><li>点击<strong>生成嵌入</strong>。结果向量会以柱状图的形式可视化显示。</li></ol><div class="tip custom-block"><p class="custom-block-title">没有嵌入模型？</p><p>如果下拉框里什么都没有，说明你需要先拉取一个：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nomic-embed-text</span></span></code></pre></div></div><h2 id="比较两段文字" tabindex="-1">比较两段文字 <a class="header-anchor" href="#比较两段文字" aria-label="Permalink to &quot;比较两段文字&quot;">​</a></h2><ol><li>在两个输入区分别输入文字。</li><li>点击<strong>比较</strong>。两段文字都会被嵌入并进行比较。</li><li><strong>余弦相似度</strong>指示器会显示两段文字在语义上有多接近： <ul><li><strong>1.0</strong> —— 含义完全相同</li><li><strong>0.7 以上</strong> —— 非常相似</li><li><strong>0.3–0.7</strong> —— 有一定关联</li><li><strong>低于 0.3</strong> —— 不相关</li></ul></li></ol><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><ul><li><strong>理解嵌入</strong> —— 看清这些数字究竟代表什么</li><li><strong>测试 RAG 的相关性</strong> —— 检查你的文档是否能匹配上用户的提问</li><li><strong>探索近义表达</strong> —— 观察模型如何理解语义关系</li><li><strong>教学</strong> —— 非常适合 AI/ML 课程中讲解向量表示</li></ul><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li>不同的嵌入模型会产生不同的向量维度和相似度分数。</li><li>简短、聚焦的文字比长段落更能得出有意义的比较结果。</li><li>结果会保存在会话中，之后可以回看。</li></ul>',15)])])}const b=t(o,[["render",r]]);export{u as __pageData,b as default};
